import React from 'react';
import styled from 'styled-components';
import placeholder from '../images/placeholder.jpg';
import emoji from '../images/emoji.jpg';

const About = () => {
    return (
        <AboutBox>
            <PicContainer />
            <Spacer />
            <TextContainer>
                <AboutText>
                    Pracuję z polskimi oraz zagranicznymi przedsiębiorcami już od ponad dziesięciu lat.
                    Ukończyłam studia magisterskie z Zarządzania Przedsiębiorstwem na Politechnice Radomskiej im. Kazimierza Pułaskiego
                    oraz studia podyplomowe z Rachunkowości na Wyższej Szkole Humanitas w Sosnowcu.
                    Oprócz tego regularnie podnoszę swoje kwalifikacje oraz znajomość przepisów poprzez uczestnictwo w kursach oraz szkoleniach,
                    Podczas mojej kariery zawodowej miałam okazję zarówno szlifować swoje umiejętności jako członek zespołów księgowych,
                    jak i nimi zarządzać. Cały ten bagaż doświadczeń sprawia, iż doskonale rozumiem jak zróżnicowane potrafią być potrzeby
                    dzisiejszych przedsiębiorców.
                </AboutText>
                <p>
                    Zapraszam
                </p>
            </TextContainer>
        </AboutBox>
    );
}

export default About

const AboutBox = styled.div`
    padding-left: 48px;
    padding-right: 48px;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: stretch;
    height: 675px;
`;

const PicContainer = styled.div`
    order: 1;
    width: 30%;
    background-image: url(${emoji});
    background-position: center;
    background-size: cover;
`;

const TextContainer = styled.div`
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    order: 3;
    width: 40%;
`;

const Spacer = styled.div`
    order: 2;
    width: 20%;
`;

const AboutText = styled.p`
    text-align: justify;
`;
